function renderProjectMediaList(){const box=$('#projectMediaList');if(!box)return;box.innerHTML='';if(!selected?.classList.contains('tile')){box.innerHTML='<div class="editor-note">Select a tile.</div>';return}const arr=projectMedia(selected.dataset.id);if(!arr.length){box.innerHTML='<div class="media-empty">No embedded project media. Public click does nothing.</div>';return}arr.forEach((m,i)=>{const row=document.createElement('div');row.className='media-row';row.innerHTML=`<span>${i+1}</span><code>${m.type==='video'?'VIDEO':'IMAGE/GIF'} · ${m.src.slice(0,42)}${m.src.length>42?'…':''}</code><button type="button">×</button>`;row.querySelector('button').onclick=()=>{PROJECTS[selected.dataset.id].splice(i,1);renderProjectMediaList();push()};box.appendChild(row)})}
function bindTextLinks(){document.addEventListener('click',e=>{if(editing)return;const t=e.target.closest('[data-type="text"][data-text-link-enabled="1"]');if(!t||!t.dataset.textLink)return;e.preventDefault();openExternal(t.dataset.textLink,t.dataset.node||'Link')})}
function bindResize(t){const h=$('.resize',t);if(!h||h.dataset.bound)return;h.dataset.bound='1';h.addEventListener('pointerdown',e=>{if(!editing)return;e.stopPropagation();const sy=e.clientY,sx=e.clientX,rect=t.getBoundingClientRect(),gr=t.parentElement.getBoundingClientRect(),col=gr.width/12;h.setPointerCapture(e.pointerId);const move=q=>{t.style.setProperty('--h',clamp(rect.height+q.clientY-sy,120,1200)+'px');t.style.setProperty('--span',clamp(Math.round((rect.width+q.clientX-sx)/col),1,12))};const up=()=>{h.removeEventListener('pointermove',move);h.removeEventListener('pointerup',up);push()};h.addEventListener('pointermove',move);h.addEventListener('pointerup',up)})}
function bindAllResize(){$$('.tile').forEach(bindResize)}
function nodeState(e){const im=e.querySelector?.('img');return{style:e.getAttribute('style')||'',html:e.dataset.type==='text'?e.innerHTML:null,data:{...e.dataset},title:$('.t-title',e)?.textContent,sub:$('.t-sub',e)?.textContent,tag:$('.tag',e)?.textContent,edges:['top','bottom','left','right'].filter(k=>e.querySelector?.('.edge.'+k)?.classList.contains('on')),img:im?.getAttribute('src')||null,placeholder:e.classList.contains('placeholder')}}
let MODEL=null,MIGRATION_REPORT=null;
function state(){MODEL=StudioModel.fromDOM({G,BRAND,HERO,LINKS,PROJECTS,prev:MODEL});return MODEL}
function hydrateMissingTile(id,a){const grid=$('.grid');if(!grid||!id.startsWith('tile-'))return null;const t=document.createElement('article');t.className='tile placeholder';Object.assign(t.dataset,{id,node:a?.data?.node||'Tile',type:'tile',hover:'none',edge:'none',action:'project',motion:'rise'});t.innerHTML='<span class="ph">Artwork placeholder</span><div class="edge top"></div><div class="edge bottom"></div><div class="edge left"></div><div class="edge right"></div><div class="tile-info"><div><div class="t-title">Project</div><div class="t-sub">Portfolio item</div></div><div class="tag">Open</div></div><div class="resize"></div>';grid.appendChild(t);bindTile(t);bindResize(t);return t}
function applyState(raw){if(!raw)return;const mig=StudioModel.migrate(raw);const m=mig.model;MODEL=m;if(mig.report.from!=='schema-4')console.info('[studio] migrated config from',mig.report.from);if(mig.report.notes&&mig.report.notes.length){console.warn('[studio] '+mig.report.notes.join(' '));later(()=>0);}const s={G:m.site,brand:m.brand,hero:m.hero,links:m.links,projects:m.projects,order:m.order,nodes:null};if(s.G&&Object.keys(s.G).length)G={...G,...s.G};if(s.brand&&Object.keys(s.brand).length)BRAND={...BRAND,...s.brand};if(s.hero&&Object.keys(s.hero).length)HERO={...HERO,...s.hero};if(s.links&&Object.keys(s.links).length)LINKS={...LINKS,...s.links};if(s.projects)PROJECTS={...s.projects};applyGlobals();applyBrand();applyHero();applyLinks();const res=StudioModel.apply(m,{hydrate:hydrateMissingTile});if(res.hydrated&&res.hydrated.length)console.info('[studio] rebuilt',res.hydrated.length,'object(s) from the published config');if(res.missing.length){const names=res.missing.map(x=>x.name||x.id).join(', ');console.warn('[studio] published config has objects this page cannot rebuild:',res.missing);status('Loaded, but '+res.missing.length+' published object(s) could not be rebuilt: '+names+'. They are still in the config, not applied.')}if(typeof bindPublicLinks==='function')bindPublicLinks();MIGRATION_REPORT={...mig.report,missing:res.missing};bindAllTiles();bindAllResize();applyBrand();layers();observe()}
function push(init=false){const str=JSON.stringify(state());if(history[hi]===str)return;history=history.slice(0,hi+1);history.push(str);if(history.length>60)history.shift();hi=history.length-1;if(!init)status('Unsaved changes')}
$('[data-undo]')?.addEventListener('click',()=>{if(hi>0){hi--;applyState(JSON.parse(history[hi]));status('Undo')}});$('[data-redo]')?.addEventListener('click',()=>{if(hi<history.length-1){hi++;applyState(JSON.parse(history[hi]));status('Redo')}});
$('[data-local]')?.addEventListener('click',()=>{localStorage.setItem(KEY,JSON.stringify(state()));status('Saved locally')});$('[data-export]')?.addEventListener('click',()=>{const a=document.createElement('a'),u=URL.createObjectURL(new Blob([JSON.stringify(state(),null,2)],{type:'application/json'}));a.href=u;a.download='studio-config.json';a.click();URL.revokeObjectURL(u)});let publishing=false;
const PUBLISH_REASONS={400:'The editor sent a payload the server rejected as invalid. This is an editor bug, not a credentials problem.',401:'Wrong username or password. Sign in again with the gear icon.',403:'The server refused the request. Check EDITOR_USER and EDITOR_PASS on the Pages project.',413:'Config is larger than the server allows. Replace uploaded images with hosted URLs.',500:'The publish function crashed on the server. Check the Pages function logs.',501:'Editor credentials are not configured on this Pages project. Set EDITOR_USER and EDITOR_PASS as secrets, then redeploy.',503:'The PORTFOLIO_CONFIG KV namespace is not bound to this Pages environment, so there is nowhere to save.'};
$('[data-publish]')?.addEventListener('click',async()=>{const btn=$('[data-publish]');if(publishing)return;if(!auth.user)return status('Not signed in. Open the editor with the gear icon and sign in before publishing.');const payload=JSON.stringify({version:VERSION,state:state()});if(payload.length>760000)return status('Too large to publish: '+Math.round(payload.length/1024)+'KB against a 760KB limit. Replace uploaded images with hosted URLs and publish again.');publishing=true;if(btn){btn.disabled=true;btn.textContent='Publishing…'}status('Publishing…');try{const ctl=new AbortController(),to=setTimeout(()=>ctl.abort(),15000);const r=await fetch('/api/config',{method:'POST',signal:ctl.signal,headers:{'Content-Type':'application/json','Authorization':'Basic '+btoa(auth.user+':'+auth.pass)},body:payload});clearTimeout(to);let body=null;try{body=await r.json()}catch{}if(r.ok&&body&&body.ok){status('Published '+new Date().toLocaleTimeString([],{hour:'numeric',minute:'2-digit'}));return}const reason=(body&&body.error)||PUBLISH_REASONS[r.status]||('The server returned '+r.status+' with no explanation.');status(r.ok?'Publish did not complete: the server accepted the request but did not confirm it saved. '+reason:'Publish failed: '+reason);}catch(e){status(e&&e.name==='AbortError'?'Publish timed out after 15 seconds. Your edits are still here; check your connection and try again.':'Could not reach the editor backend. Your edits are still here — nothing was lost. Check your connection and try again.');}finally{publishing=false;if(btn){btn.disabled=false;btn.textContent='Publish live'}}});
window.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.modal')?.classList.remove('open');$('.redirect-modal')?.classList.remove('open');$('.login')?.classList.remove('open');document.body.style.overflow=''}if(!editing&&$('.modal')?.classList.contains('open')&&e.key==='ArrowLeft'){e.preventDefault();jumpMedia(-1)}if(!editing&&$('.modal')?.classList.contains('open')&&e.key==='ArrowRight'){e.preventDefault();jumpMedia(1)}if(editing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?$('[data-redo]')?.click():$('[data-undo]')?.click()}});
(async()=>{ensureProjectShell();bindPublicLinks();bindAllTiles();bindAllResize();bindTextLinks();bindBaseControls();bindSiteControls();bindUploads();applyGlobals();applyBrand();applyHero();applyLinks();initLoader();observe();let loaded=false;if(location.protocol!=='file:')try{const r=await fetch('/api/config?version='+VERSION,{cache:'no-store'});if(r.ok){const j=await r.json();if(j.state){applyState(j.state);loaded=true}}}catch{}if(!loaded)try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(s)applyState(s)}catch{}push(true)})();